    Coupon = apps.get_model("shop", "Coupon")
    for coupon in Coupon.objects.all():
        code = (coupon.code or "").strip().upper()
        if code == coupon.code:
            continue
        if Coupon.objects.filter(code=code).exclude(pk=coupon.pk).exists():
            continue
        coupon.code = code
        coupon.save(update_fields=["code"])


